48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    /**
108	     * Rejects an owner payload that is missing or blank in any of the required fields
109	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
110	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
111	     * value as present; this guard closes that gap so a blank in any required field is
112	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
113	     * the name of each offending field.
114	     */
115	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto) {
116	        List<String> missing = new ArrayList<>();
117	        if (isBlank(ownerFieldsDto.getFirstName())) {
118	            missing.add("firstName");
119	        }
120	        if (isBlank(ownerFieldsDto.getLastName())) {
121	            missing.add("lastName");
122	        }
123	        if (isBlank(ownerFieldsDto.getAddress())) {
124	            missing.add("address");
125	        }
126	        if (isBlank(ownerFieldsDto.getCity())) {
127	            missing.add("city");
128	        }
129	        if (isBlank(ownerFieldsDto.getTelephone())) {
130	            missing.add("telephone");
131	        }
132	        if (!missing.isEmpty()) {
133	            throw new MissingOwnerFieldsException(missing);
134	        }
135	    }
136	
137	    private static boolean isBlank(String value) {
138	        return value == null || value.isBlank();
139	    }
140	
141	    /**
142	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
143	     */
144	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
145	
146	    /**
147	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
148	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
149	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
150	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
151	     * stored as '+61412345678'. A value that cannot form a valid E.164 number is rejected via
152	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
153	     */
154	    private static String normalizeTelephone(String telephone) {
155	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
156	        String e164;
157	        if (cleaned.startsWith("+")) {
158	            e164 = cleaned;
159	        } else {
160	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
161	            e164 = "+61" + national;
162	        }
163	        if (!E164_PATTERN.matcher(e164).matches()) {
164	            throw new InvalidTelephoneException(telephone);
165	        }
166	        return e164;
167	    }
168	
169	    /**
170	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
171	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
172	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
173	     */
174	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
175	
176	    /**
177	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
178	     * optional). When present it must be a syntactically valid address; a valid value is
179	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
180	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
181	     */
182	    private static String normalizeEmail(String email) {
183	        if (email == null) {
184	            return null;
185	        }
186	        if (!EMAIL_PATTERN.matcher(email).matches()) {
187	            throw new InvalidEmailException(email);
188	        }
189	        return email.toLowerCase(Locale.ROOT);
190	    }
191	
192	    /**
193	     * Rejects a create whose normalized telephone is already used by another owner. Each
194	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
195	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
196	     * the format each was originally entered in. An existing value that cannot form a valid E.164
197	     * number is skipped rather than colliding. A match is reported via
198	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
199	     */
200	    private void rejectDuplicateTelephone(String normalizedTelephone) {
201	        for (Owner existing : this.clinicService.findAllOwners()) {
202	            String existingE164;
203	            try {
204	                existingE164 = normalizeTelephone(existing.getTelephone());
205	            } catch (InvalidTelephoneException ex) {
206	                continue;
207	            }
208	            if (normalizedTelephone.equals(existingE164)) {
209	                throw new DuplicateTelephoneException(normalizedTelephone);
210	            }
211	        }
212	    }
213	
214	    /**
215	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
216	     * where {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN}
217	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners
218	     * (e.g. {@code 'SMI-0007'}).
219	     */
220	    private String nextCustomerCode(String lastName) {
221	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
222	        int sequence = this.clinicService.findAllOwners().size() + 1;
223	        return String.format("%s-%04d", last3, sequence);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
229	        rejectMissingOrBlankFields(ownerFieldsDto);
230	        HttpHeaders headers = new HttpHeaders();
231	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
232	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
233	        rejectDuplicateTelephone(normalizedTelephone);
234	        owner.setTelephone(normalizedTelephone);
235	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
236	        if (owner.getRegistrationDate() == null) {
237	            owner.setRegistrationDate(LocalDate.now());
238	        }
239	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
240	        this.clinicService.saveOwner(owner);
241	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
242	        headers.setLocation(UriComponentsBuilder.newInstance()
243	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
244	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
245	    }
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
250	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
251	        if (currentOwner == null) {
252	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	        }
254	        currentOwner.setAddress(ownerFieldsDto.getAddress());
255	        currentOwner.setCity(ownerFieldsDto.getCity());
256	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
257	        currentOwner.setLastName(ownerFieldsDto.getLastName());
258	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
259	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
260	        this.clinicService.saveOwner(currentOwner);
261	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Transactional
266	    @Override
267	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
268	        Owner owner = this.clinicService.findOwnerById(ownerId);
269	        if (owner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        this.clinicService.deleteOwner(owner);
273	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
279	        Owner owner = this.clinicService.findOwnerById(ownerId);
280	        if (owner == null) {
281	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
282	        }
283	        HttpHeaders headers = new HttpHeaders();
284	        Pet pet = petMapper.toPet(petFieldsDto);
285	        owner.setId(ownerId);
286	        pet.setOwner(owner);
287	        pet.getType().setName(null);
288	        this.clinicService.savePet(pet);
289	        PetDto petDto = petMapper.toPetDto(pet);
290	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
291	            .buildAndExpand(pet.getId()).toUri());
292	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
293	    }
294	
295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Override
297	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
298	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
299	        if (currentOwner != null) {
300	            Pet currentPet = this.clinicService.findPetById(petId);
301	            if (currentPet != null) {
302	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
303	                currentPet.setName(petFieldsDto.getName());
304	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
305	                this.clinicService.savePet(currentPet);
306	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
307	            }
308	        }
309	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
310	    }
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
315	        HttpHeaders headers = new HttpHeaders();
316	        Visit visit = visitMapper.toVisit(visitFieldsDto);
317	        Pet pet = new Pet();
318	        pet.setId(petId);
319	        visit.setPet(pet);
320	        this.clinicService.saveVisit(visit);
321	        VisitDto visitDto = visitMapper.toVisitDto(visit);
322	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
323	            .buildAndExpand(visit.getId()).toUri());
324	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
325	    }
326	
327	
328	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
329	    @Override
330	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
331	        Owner owner = this.clinicService.findOwnerById(ownerId);
332	        if (owner != null) {
333	            Pet pet = owner.getPet(petId);
334	            if (pet != null) {
335	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
336	            }
337	        }
338	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
339	    }
340	}
